final class Packrat {
    struct Key: Hashable { let rule: Int; let pos: Int }
    enum Memo { case ok(node: Node, next: Int); case failed }
    private var memo: [Key: Memo] = [:]
    func rule(_ r: Int, _ pos: Int) -> Memo {
        let k = Key(rule: r, pos: pos)
        if let hit = memo[k] { return hit }     // success or .failed
        let m = ruleImpl(r, pos)                // may backtrack
        memo[k] = m                             // failures are cached too
        return m
    }
}
